return ['domain'=>'blockstudio','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ta_IN','project-id-version'=>'Blockstudio','po-revision-date'=>'2026-10-23 15:38+0000','messages'=>['Blockstudio'=>'Blockstudio','The "%1$s" attribute on a %2$s block tag is dropped because the block declares no field with that id. Declare the field, or write it as a data-, aria- or html- attribute to put it on the root element.'=>'%2$s பிளாக் குறிச்சொல்லில் உள்ள "%1$s" பண்புக்கூறு நீக்கப்பட்டது; அந்த ID கொண்ட புலம் பிளாக் அறிவிப்பில் இல்லை. அந்தப் புலத்தை அறிவிக்கவும் அல்லது மூல உறுப்பில் சேர்க்க அதை data-, aria- அல்லது html- பண்புக்கூறாக எழுதவும்.','This storage key is not declared by the block or its extensions.'=>'இந்த சேமிப்பக விசை பிளாக் அல்லது அதன் நீட்டிப்புகளால் அறிவிக்கப்படவில்லை.','This top-level key is not an attribute of the block, so it is ignored.'=>'இந்த மேல்நிலை விசை தொகுதியின் பண்புக்கூறு அல்ல; எனவே புறக்கணிக்கப்படுகிறது.','This key is only read inside the blockstudio object, which is missing.'=>'இந்த விசை blockstudio பொருளுக்குள் மட்டுமே படிக்கப்படுகிறது; அந்தப் பொருள் இல்லை.','This value is not among the field options.'=>'இந்த மதிப்பு புல விருப்பங்களில் இல்லை.','This value has an unsupported shape for the field.'=>'இந்த மதிப்பின் வடிவம் இந்தப் புலத்துக்கு ஆதரிக்கப்படவில்லை.','This repeater has fewer rows than its minimum.'=>'இந்த மீளுருவாக்கியில் குறைந்தபட்சத்தைவிடக் குறைவான வரிசைகள் உள்ளன.','This repeater has more rows than its maximum.'=>'இந்த மீளுருவாக்கியில் அதிகபட்சத்தைவிட அதிகமான வரிசைகள் உள்ளன.','This storage key has conflicting field definitions.'=>'இந்தச் சேமிப்பக விசைக்கு முரண்படும் புல வரையறைகள் உள்ளன.','The nested field value overrides this top-level value.'=>'உட்பொதிந்த புலத்தின் மதிப்பு இந்த மேல்நிலை மதிப்பை மேலெழுதுகிறது.','Extension bindings read this value only from blockstudio.attributes.'=>'நீட்டிப்பு பிணைப்புகள் இந்த மதிப்பை blockstudio.attributes இலிருந்து மட்டுமே படிக்கும்.','Blockstudio field values must be stored in an object.'=>'Blockstudio புல மதிப்புகள் ஒரு பொருளில் சேமிக்கப்பட வேண்டும்.','Blockstudio is preparing its block cache. Please retry shortly.'=>'Blockstudio அதன் பிளாக் தற்காலிகச் சேமிப்பைத் தயாரிக்கிறது. சிறிது நேரம் கழித்து மீண்டும் முயற்சிக்கவும்.','Canvas is disabled.'=>'கேன்வாஸ் முடக்கப்பட்டுள்ளது.','Invalid or missing CSRF token.'=>'CSRF டோக்கன் தவறானது அல்லது இல்லை.','Authentication required.'=>'அங்கீகாரம் தேவை.','Insufficient permissions.'=>'போதிய அனுமதிகள் இல்லை.','Validation failed.'=>'சரிபார்ப்பு தோல்வியடைந்தது.','Record not found.'=>'பதிவு கிடைக்கவில்லை.','Invalid islands request.'=>'தவறான தீவுகள் கோரிக்கை.','Too many islands requested.'=>'மிக அதிகமான தீவுகள் கோரப்பட்டன.','Invalid island block.'=>'தவறான தீவுப் பிளாக்.','Invalid island signature.'=>'தவறான தீவு கையொப்பம்.','Sorry, you are not allowed to read blocks of this post.'=>'மன்னிக்கவும், இந்தப் பதிவின் பிளாக்குகளைப் படிக்க உங்களுக்கு அனுமதி இல்லை.','Sorry, you are not allowed to read blocks as this user.'=>'மன்னிக்கவும், இந்தப் பயனராக பிளாக்குகளைப் படிக்க உங்களுக்கு அனுமதி இல்லை.','Invalid block.'=>'தவறான பிளாக்.','Method not allowed.'=>'இந்த முறை அனுமதிக்கப்படவில்லை.','Block not found.'=>'பிளாக் கிடைக்கவில்லை.','Function not found.'=>'செயல்பாடு கிடைக்கவில்லை.','Function is not callable.'=>'செயல்பாட்டை அழைக்க முடியாது.','Blockstudio ignored invalid configuration values:'=>'Blockstudio தவறான உள்ளமைவு மதிப்புகளைப் புறக்கணித்தது:','%s: Link text'=>'%s: இணைப்பு உரை','%s: URL'=>'%s: URL','True'=>'உண்மை','False'=>'பொய்','Could not load database records.'=>'தரவுத்தளப் பதிவுகளை ஏற்ற முடியவில்லை.','This database has no records yet.'=>'இந்தத் தரவுத்தளத்தில் இதுவரை பதிவுகள் இல்லை.','No Blockstudio databases are registered.'=>'Blockstudio தரவுத்தளங்கள் எதுவும் பதிவு செய்யப்படவில்லை.','The selected database could not be found.'=>'தேர்ந்தெடுக்கப்பட்ட தரவுத்தளத்தைக் கண்டறிய முடியவில்லை.','Overview'=>'மேலோட்டம்','Registry'=>'பதிவகம்','Databases'=>'தரவுத்தளங்கள்','Docs'=>'ஆவணங்கள்','No Blockstudio overview data is available.'=>'Bloc